 private const TYPES=['topographical','boundary','beacon_relocation','subdivision','consolidation','sectional_title','servitude','lease_diagram','general_plan','as_built','other'];private const OBS=['control_point','benchmark','beacon','boundary_marker','detail_point','other'];private const OBS_STATUS=['observed','verified','rejected','superseded'];private const DEL=['topographical_plan','cadastral_diagram','general_plan','beacon_certificate','control_report','servitude_diagram','sectional_title_plan','as_built_plan','coordinate_schedule','other'];private const DEL_STATUS=['draft','pending_review','complete','submitted_externally','accepted','rejected','superseded'];public function __construct(private PDO$pdo){}
 public function create(string$o,string$u,string$r,array$i):array{$this->writer($o,$u,$r);$p=$this->id($i['projectId']??null,'survey_project_not_found');$this->project($o,$p);$id=Identifier::generate();$v=['id'=>$id,'o'=>$o,'p'=>$p,'number'=>$this->text($i['jobNumber']??null,80,'survey_job_number_required'),'type'=>$this->choice($i['surveyType']??null,self::TYPES,'survey_type_invalid'),'title'=>$this->text($i['title']??null,220,'survey_title_required'),'role'=>$this->role($i['responsibleRole']??null),'crs'=>$this->text($i['coordinateReferenceSystem']??null,180,'survey_crs_required'),'datum'=>$this->text($i['verticalDatum']??null,180,'survey_vertical_datum_required'),'sources'=>$this->json($this->sources($i['sourceBasis']??null)),'u'=>$u];try{$this->pdo->beginTransaction();$this->pdo->prepare('INSERT INTO survey_jobs(id,organisation_id,project_id,job_number,survey_type,title,responsible_role,coordinate_reference_system,vertical_datum,source_basis,created_by) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),:number,:type,:title,:role,:crs,:datum,:sources,UNHEX(:u))')->execute($v);(new AuditService($this->pdo))->append($o,$u,'survey.job.created','survey_job',$id,['projectId'=>$p,'surveyType'=>$v['type'],'surveyorGeneralApprovalClaimed'=>false]);$this->pdo->commit();}catch(PDOException$e){if($this->pdo->inTransaction())$this->pdo->rollBack();if((string)$e->getCode()==='23000')throw new SurveyJobException('survey_job_number_exists');throw$e;}return$this->get($o,$u,$id);}
 public function addObservation(string$o,string$u,string$r,string$id,int$v,array$i):array{$this->writer($o,$u,$r);$job=$this->draft($o,$u,$id,$v);$payload=$i['payload']??null;if(!is_array($payload))throw new SurveyJobException('survey_payload_invalid');$oid=Identifier::generate();try{$this->pdo->beginTransaction();$this->lock($o,$id,$v);$this->pdo->prepare('INSERT INTO survey_observations(id,organisation_id,project_id,survey_job_id,point_code,observation_type,easting,northing,elevation,status,source_reference,source_url,observed_on,payload,created_by) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),UNHEX(:job),:code,:type,:east,:north,:elevation,:status,:ref,:url,:date,:payload,UNHEX(:u))')->execute(['id'=>$oid,'o'=>$o,'p'=>$job['projectId'],'job'=>$id,'code'=>$this->text($i['pointCode']??null,80,'survey_point_code_required'),'type'=>$this->choice($i['observationType']??null,self::OBS,'survey_observation_type_invalid'),'east'=>$this->decimal($i['easting']??null,'survey_easting_invalid'),'north'=>$this->decimal($i['northing']??null,'survey_northing_invalid'),'elevation'=>$this->decimal($i['elevation']??null,'survey_elevation_invalid'),'status'=>$this->choice($i['status']??null,self::OBS_STATUS,'survey_observation_status_invalid'),'ref'=>$this->text($i['sourceReference']??null,180,'survey_source_reference_required'),'url'=>$this->url($i['sourceUrl']??null),'date'=>$this->date($i['observedAt']??null),'payload'=>$this->json($payload),'u'=>$u]);$this->bump($o,$id,$v);(new AuditService($this->pdo))->append($o,$u,'survey.observation.created','survey_job',$id,['observationId'=>$oid]);$this->pdo->commit();}catch(Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}$row=$this->observation($o,$oid);$row['jobVersion']=$v+1;return$row;}
 public function addDeliverable(string$o,string$u,string$r,string$id,int$v,array$i):array{$this->writer($o,$u,$r);$job=$this->draft($o,$u,$id,$v);$payload=$i['payload']??null;if(!is_array($payload))throw new SurveyJobException('survey_payload_invalid');$did=Identifier::generate();try{$this->pdo->beginTransaction();$this->lock($o,$id,$v);$this->pdo->prepare('INSERT INTO survey_deliverables(id,organisation_id,project_id,survey_job_id,deliverable_type,title,status,external_reference,source_url,payload,created_by) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),UNHEX(:job),:type,:title,:status,:ref,:url,:payload,UNHEX(:u))')->execute(['id'=>$did,'o'=>$o,'p'=>$job['projectId'],'job'=>$id,'type'=>$this->choice($i['deliverableType']??null,self::DEL,'survey_deliverable_type_invalid'),'title'=>$this->text($i['title']??null,220,'survey_deliverable_title_required'),'status'=>$this->choice($i['status']??null,self::DEL_STATUS,'survey_deliverable_status_invalid'),'ref'=>$this->text($i['externalReference']??null,180,'survey_source_reference_required'),'url'=>$this->url($i['sourceUrl']??null),'payload'=>$this->json($payload),'u'=>$u]);$this->bump($o,$id,$v);(new AuditService($this->pdo))->append($o,$u,'survey.deliverable.created','survey_job',$id,['deliverableId'=>$did]);$this->pdo->commit();}catch(Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}return$this->get($o,$u,$id);}
 public function estimateFees(string$o,string$u,string$r,string$id,int$v,array$i):array{$this->writer($o,$u,$r);$this->draft($o,$u,$id,$v);$field=$this->hundredths($i['fieldDays']??null,'survey_field_days_invalid');$office=$this->hundredths($i['officeDays']??null,'survey_office_days_invalid');$travel=$this->hundredths($i['travelDistanceKm']??null,'survey_travel_invalid');$fieldRate=$this->money($i['fieldDayRateCents']??null);$officeRate=$this->money($i['officeDayRateCents']??null);$travelRate=$this->money($i['travelRateCentsPerKm']??null);$complexity=$this->money($i['complexityAllowanceCents']??null);$statutory=$this->money($i['statutoryFeeCents']??null);$payload=['fieldDays'=>$i['fieldDays'],'fieldDayRateCents'=>$fieldRate,'officeDays'=>$i['officeDays'],'officeDayRateCents'=>$officeRate,'travelDistanceKm'=>$i['travelDistanceKm'],'travelRateCentsPerKm'=>$travelRate,'complexityAllowanceCents'=>$complexity,'statutoryFeeCents'=>$statutory,'statutorySourceTitle'=>$this->text($i['statutorySourceTitle']??null,220,'survey_statutory_source_required'),'statutorySourceUrl'=>$this->url($i['statutorySourceUrl']??null),'statutorySourceRetrievedAt'=>$this->date($i['statutorySourceRetrievedAt']??null),'surveyorGeneralApprovalClaimed'=>false];$private=intdiv($field*$fieldRate+50,100)+intdiv($office*$officeRate+50,100)+intdiv($travel*$travelRate+50,100)+$complexity;$total=$private+$statutory;try{$this->pdo->beginTransaction();$this->lock($o,$id,$v);$s=$this->pdo->prepare("UPDATE survey_jobs SET fee_payload=:payload,private_professional_fee_cents=:private,statutory_fee_cents=:statutory,total_fee_cents=:total,version=version+1 WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o) AND version=:v AND status='draft'");$s->execute(['payload'=>$this->json($payload),'private'=>$private,'statutory'=>$statutory,'total'=>$total,'id'=>$id,'o'=>$o,'v'=>$v]);if($s->rowCount()!==1)throw new SurveyJobException('survey_version_conflict');(new AuditService($this->pdo))->append($o,$u,'survey.fees.estimated','survey_job',$id,['privateProfessionalFeeCents'=>$private,'statutoryFeeCents'=>$statutory]);$this->pdo->commit();}catch(Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}return['jobVersion'=>$v+1,'privateProfessionalFeeCents'=>$private,'statutoryFeeCents'=>$statutory,'totalFeeCents'=>$total,'feePayload'=>$payload];}
 public function issue(string$o,string$u,string$r,string$id,int$v,bool$confirmed,string$role,string$reason,string$reference):array{$this->writer($o,$u,$r);if(!$confirmed)throw new SurveyJobException('survey_issue_confirmation_required');$job=$this->draft($o,$u,$id,$v);$role=$this->role($role);if($role!==$job['responsibleRole']||!$this->canActAs($o,$u,$job['projectId'],$role))throw new SurveyJobException('survey_issue_role_denied');if(count(array_filter($job['observations'],fn($x)=>$x['status']==='verified'))<2||count(array_filter($job['deliverables'],fn($x)=>$x['status']==='complete'))<1||$job['feePayload']===null)throw new SurveyJobException('survey_issue_evidence_incomplete');$reason=$this->text($reason,500,'survey_issue_reason_required');$reference=$this->text($reference,180,'survey_issue_reference_required');$snapshot=['job'=>array_intersect_key($job,array_flip(['id','projectId','jobNumber','surveyType','title','responsibleRole','coordinateReferenceSystem','verticalDatum','sourceBasis','feePayload','privateProfessionalFeeCents','statutoryFeeCents','totalFeeCents'])),'observations'=>$job['observations'],'deliverables'=>$job['deliverables'],'issue'=>['externalReference'=>$reference,'reason'=>$reason,'humanConfirmed'=>true,'professionalRole'=>$role,'surveyorGeneralApprovalClaimed'=>false,'officialCoordinatesClaimed'=>false]];$json=$this->json($snapshot);$sha=hash('sha256',$json);$project=$this->project($o,$job['projectId']);try{$this->pdo->beginTransaction();$this->lock($o,$id,$v);$record=(new ProjectRecordService($this->pdo))->issue(new ProjectContext($o,$u,$job['projectId'],$r),ProjectPhase::from($project['currentPhase']),'survey_geomatics','survey_issue',$job['jobNumber'].' '.$job['title'],'issued',['surveyJobId'=>$id,'surveyType'=>$job['surveyType'],'snapshotSha256'=>$sha,'surveyorGeneralApprovalClaimed'=>false],['required'=>true,'humanApprovalConfirmed'=>true,'approvedBy'=>$u,'professionalRole'=>$role,'reason'=>$reason]);$s=$this->pdo->prepare("UPDATE survey_jobs SET status='issued',version=version+1,issue_reference=:ref,issue_reason=:reason,snapshot_payload=:snapshot,snapshot_sha256=:sha,project_record_id=UNHEX(:record),issued_by=UNHEX(:u),issued_at=UTC_TIMESTAMP(6) WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o) AND version=:v AND status='draft'");$s->execute(['ref'=>$reference,'reason'=>$reason,'snapshot'=>$json,'sha'=>$sha,'record'=>$record,'u'=>$u,'id'=>$id,'o'=>$o,'v'=>$v]);if($s->rowCount()!==1)throw new SurveyJobException('survey_version_conflict');(new AuditService($this->pdo))->append($o,$u,'survey.job.issued','survey_job',$id,['snapshotSha256'=>$sha,'projectRecordId'=>$record,'surveyorGeneralApprovalClaimed'=>false]);$this->pdo->commit();}catch(Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}return$this->get($o,$u,$id);}
 public function get(string$o,string$u,string$id):array{$this->member($o,$u);$s=$this->pdo->prepare("SELECT LOWER(HEX(id)) id,LOWER(HEX(project_id)) project_id,job_number,survey_type,title,responsible_role,coordinate_reference_system,vertical_datum,source_basis,status,version,fee_payload,private_professional_fee_cents,statutory_fee_cents,total_fee_cents,issue_reference,issue_reason,snapshot_payload,snapshot_sha256,LOWER(HEX(project_record_id)) project_record_id,issued_at,created_at FROM survey_jobs WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o)");$s->execute(['id'=>$this->id($id,'survey_job_not_found'),'o'=>$o]);$x=$s->fetch();if(!is_array($x))throw new SurveyJobException('survey_job_not_found');$snapshot=$x['snapshot_payload']===null?null:json_decode((string)$x['snapshot_payload'],true,64,JSON_THROW_ON_ERROR);if($snapshot!==null&&!hash_equals((string)$x['snapshot_sha256'],hash('sha256',$this->json($snapshot))))throw new SurveyJobException('survey_integrity_failed');return['id'=>$x['id'],'projectId'=>$x['project_id'],'jobNumber'=>$x['job_number'],'surveyType'=>$x['survey_type'],'title'=>$x['title'],'responsibleRole'=>$x['responsible_role'],'coordinateReferenceSystem'=>$x['coordinate_reference_system'],'verticalDatum'=>$x['vertical_datum'],'sourceBasis'=>json_decode((string)$x['source_basis'],true,64,JSON_THROW_ON_ERROR),'status'=>$x['status'],'version'=>(int)$x['version'],'feePayload'=>$x['fee_payload']===null?null:json_decode((string)$x['fee_payload'],true,64,JSON_THROW_ON_ERROR),'privateProfessionalFeeCents'=>$x['private_professional_fee_cents']===null?null:(int)$x['private_professional_fee_cents'],'statutoryFeeCents'=>$x['statutory_fee_cents']===null?null:(int)$x['statutory_fee_cents'],'totalFeeCents'=>$x['total_fee_cents']===null?null:(int)$x['total_fee_cents'],'issueReference'=>$x['issue_reference'],'issueReason'=>$x['issue_reason'],'snapshot'=>$snapshot,'snapshotSha256'=>$x['snapshot_sha256'],'projectRecordId'=>$x['project_record_id'],'issuedAt'=>$x['issued_at'],'createdAt'=>$x['created_at'],'observations'=>$this->observations($o,$id),'deliverables'=>$this->deliverables($o,$id),'surveyorGeneralApprovalClaimed'=>false,'officialCoordinatesClaimed'=>false];}
 private function observations(string$o,string$id):array{$s=$this->pdo->prepare('SELECT LOWER(HEX(id)) id,point_code,observation_type,easting,northing,elevation,status,source_reference,source_url,observed_on,payload,created_at FROM survey_observations WHERE organisation_id=UNHEX(:o) AND survey_job_id=UNHEX(:id) ORDER BY created_at,id');$s->execute(['o'=>$o,'id'=>$id]);$out=[];foreach($s as$x)$out[]=$this->mapObservation($x);return$out;}private function observation(string$o,string$id):array{$s=$this->pdo->prepare('SELECT LOWER(HEX(id)) id,point_code,observation_type,easting,northing,elevation,status,source_reference,source_url,observed_on,payload,created_at FROM survey_observations WHERE organisation_id=UNHEX(:o) AND id=UNHEX(:id)');$s->execute(['o'=>$o,'id'=>$id]);$x=$s->fetch();if(!is_array($x))throw new SurveyJobException('survey_observation_not_found');return$this->mapObservation($x);}private function mapObservation(array$x):array{return['id'=>$x['id'],'pointCode'=>$x['point_code'],'observationType'=>$x['observation_type'],'easting'=>$x['easting'],'northing'=>$x['northing'],'elevation'=>$x['elevation'],'status'=>$x['status'],'sourceReference'=>$x['source_reference'],'sourceUrl'=>$x['source_url'],'observedAt'=>$x['observed_on'],'payload'=>json_decode((string)$x['payload'],true,64,JSON_THROW_ON_ERROR),'createdAt'=>$x['created_at']];}
 private function deliverables(string$o,string$id):array{$s=$this->pdo->prepare('SELECT LOWER(HEX(id)) id,deliverable_type,title,status,external_reference,source_url,payload,created_at FROM survey_deliverables WHERE organisation_id=UNHEX(:o) AND survey_job_id=UNHEX(:id) ORDER BY created_at,id');$s->execute(['o'=>$o,'id'=>$id]);$out=[];foreach($s as$x)$out[]=['id'=>$x['id'],'deliverableType'=>$x['deliverable_type'],'title'=>$x['title'],'status'=>$x['status'],'externalReference'=>$x['external_reference'],'sourceUrl'=>$x['source_url'],'payload'=>json_decode((string)$x['payload'],true,64,JSON_THROW_ON_ERROR),'createdAt'=>$x['created_at']];return$out;}
 private function draft(string$o,string$u,string$id,int$v):array{$j=$this->get($o,$u,$id);if($j['status']!=='draft')throw new SurveyJobException('survey_job_issued');if($j['version']!==$v)throw new SurveyJobException('survey_version_conflict');return$j;}private function lock(string$o,string$id,int$v):void{$s=$this->pdo->prepare('SELECT version,status FROM survey_jobs WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o) FOR UPDATE');$s->execute(['id'=>$id,'o'=>$o]);$x=$s->fetch();if(!is_array($x))throw new SurveyJobException('survey_job_not_found');if($x['status']!=='draft')throw new SurveyJobException('survey_job_issued');if((int)$x['version']!==$v)throw new SurveyJobException('survey_version_conflict');}private function bump(string$o,string$id,int$v):void{$s=$this->pdo->prepare("UPDATE survey_jobs SET version=version+1 WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o) AND version=:v AND status='draft'");$s->execute(['id'=>$id,'o'=>$o,'v'=>$v]);if($s->rowCount()!==1)throw new SurveyJobException('survey_version_conflict');}
 private function project(string$o,string$p):array{$s=$this->pdo->prepare('SELECT current_phase currentPhase,lead_professional_role leadProfessionalRole,LOWER(HEX(created_by)) createdBy FROM projects WHERE id=UNHEX(:p) AND organisation_id=UNHEX(:o)');$s->execute(['p'=>$this->id($p,'survey_project_not_found'),'o'=>$o]);$x=$s->fetch();if(!is_array($x))throw new SurveyJobException('survey_project_not_found');return$x;}private function canActAs(string$o,string$u,string$projectId,string$r):bool{$project=$this->project($o,$projectId);$assigned=hash_equals($project['createdBy'],$u)&&$project['leadProfessionalRole']===$r;if(!$assigned){$s=$this->pdo->prepare("SELECT 1 FROM project_team_members WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) AND user_id=UNHEX(:u) AND status='active' AND discipline=:r AND verification_grade IN ('manually_reviewed','externally_verified')");$s->execute(['o'=>$o,'p'=>$projectId,'u'=>$u,'r'=>$r]);$assigned=$s->fetchColumn()!==false;}if(!$assigned)return false;$s=$this->pdo->prepare("SELECT 1 FROM verification_records WHERE organisation_id=UNHEX(:o) AND user_id=UNHEX(:u) AND kind='professional_registration' AND grade IN ('manually_reviewed','externally_verified') AND reviewed_by IS NOT NULL AND reviewed_by<>user_id AND (expires_on IS NULL OR expires_on>=UTC_DATE()) LIMIT 1");$s->execute(['o'=>$o,'u'=>$u]);return$s->fetchColumn()!==false;}
 private function writer(string$o,string$u,string$r):void{if(!in_array($r,['owner','admin','member'],true))throw new SurveyJobException('survey_permission_denied');$this->member($o,$u);}private function member(string$o,string$u):void{$s=$this->pdo->prepare("SELECT 1 FROM organisation_memberships WHERE organisation_id=UNHEX(:o) AND user_id=UNHEX(:u) AND status='active'");$s->execute(['o'=>$this->id($o,'survey_permission_denied'),'u'=>$this->id($u,'survey_permission_denied')]);if($s->fetchColumn()===false)throw new SurveyJobException('survey_permission_denied');}
 private function sources(mixed$v):array{if(!is_array($v)||$v===[])throw new SurveyJobException('survey_source_basis_required');$out=[];foreach($v as$x){if(!is_array($x))throw new SurveyJobException('survey_source_basis_invalid');$out[]=['title'=>$this->text($x['title']??null,220,'survey_source_title_required'),'url'=>$this->url($x['url']??null),'retrievedAt'=>$this->date($x['retrievedAt']??null)];}return$out;}private function decimal(mixed$v,string$e):string{if(!is_string($v)||preg_match('/\A-?\d{1,15}(?:\.\d{1,4})?\z/',$v)!==1)throw new SurveyJobException($e);return$v;}private function hundredths(mixed$v,string$e):int{if(!is_string($v)||preg_match('/\A\d{1,7}(?:\.\d{1,2})?\z/',$v)!==1)throw new SurveyJobException($e);[$a,$b]=array_pad(explode('.',$v,2),2,'');return((int)$a*100)+(int)str_pad($b,2,'0');}private function money(mixed$v):int{if(!is_int($v)||$v<0||$v>100000000000)throw new SurveyJobException('survey_money_invalid');return$v;}private function url(mixed$v):string{$v=$this->text($v,1000,'survey_source_url_required');if(filter_var($v,FILTER_VALIDATE_URL)===false||!in_array(parse_url($v,PHP_URL_SCHEME),['http','https'],true))throw new SurveyJobException('survey_source_url_invalid');return$v;}private function date(mixed$v):string{$v=$this->text($v,10,'survey_source_date_required');$d=DateTimeImmutable::createFromFormat('!Y-m-d',$v);if(!$d||$d->format('Y-m-d')!==$v)throw new SurveyJobException('survey_source_date_invalid');return$v;}private function id(mixed$v,string$e):string{if(!is_string($v)||preg_match('/\A[a-f0-9]{32}\z/i',$v)!==1)throw new SurveyJobException($e);return strtolower($v);}private function role(mixed$v):string{$v=$this->text($v,80,'survey_role_invalid');if(preg_match('/\A[a-z][a-z0-9_]{1,79}\z/',$v)!==1)throw new SurveyJobException('survey_role_invalid');return$v;}private function choice(mixed$v,array$a,string$e):string{if(!is_string($v)||!in_array($v,$a,true))throw new SurveyJobException($e);return$v;}private function text(mixed$v,int$m,string$e):string{$v=is_string($v)?trim($v):'';if($v===''||mb_strlen($v)>$m)throw new SurveyJobException($e);return$v;}private function json(mixed$v):string{return json_encode($v,JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);}
